// cart-checks — a small cart with VAT and a server-checked coupon.
// The coupon lookup goes to /api/coupon so tests can intercept it.

const VAT_RATE = 0.075;
const PRODUCTS = [
  { id: "beans", name: "Honey beans (1kg)", price: 1800 },
  { id: "rice", name: "Basmati rice (5kg)", price: 9500 },
  { id: "oil", name: "Groundnut oil (1L)", price: 2600 },
];

let cart = []; // { id, qty }
let discountPct = 0;

const catalog = document.getElementById("catalog");
const linesEl = document.getElementById("lines");
const emptyEl = document.getElementById("empty");
const totalsEl = document.getElementById("totals");
const couponMsg = document.getElementById("coupon-msg");

const naira = (n) => "₦" + n.toLocaleString("en-NG", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const product = (id) => PRODUCTS.find((p) => p.id === id);

function renderCatalog() {
  catalog.innerHTML = "";
  for (const p of PRODUCTS) {
    const row = document.createElement("div");
    row.className = "product";
    row.innerHTML = `<span>${p.name} — ${naira(p.price)}</span>`;
    const btn = document.createElement("button");
    btn.className = "primary";
    btn.textContent = "Add to cart";
    btn.dataset.add = p.id;
    btn.addEventListener("click", () => addToCart(p.id));
    row.appendChild(btn);
    catalog.appendChild(row);
  }
}

function addToCart(id) {
  const item = cart.find((c) => c.id === id);
  if (item) item.qty += 1;
  else cart.push({ id, qty: 1 });
  render();
}

function setQty(id, delta) {
  const item = cart.find((c) => c.id === id);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) cart = cart.filter((c) => c.id !== id);
  render();
}

function subtotal() {
  return cart.reduce((sum, c) => sum + product(c.id).price * c.qty, 0);
}

function render() {
  linesEl.innerHTML = "";
  for (const c of cart) {
    const p = product(c.id);
    const line = document.createElement("div");
    line.className = "line";
    line.dataset.line = c.id;
    line.innerHTML = `<span>${p.name}</span>`;
    const controls = document.createElement("span");
    controls.className = "qty";
    controls.innerHTML = `
      <button type="button" aria-label="Decrease ${p.name}" data-dec="${c.id}">−</button>
      <span data-qty="${c.id}">${c.qty}</span>
      <button type="button" aria-label="Increase ${p.name}" data-inc="${c.id}">+</button>
      <button type="button" aria-label="Remove ${p.name}" data-remove="${c.id}">✕</button>`;
    line.appendChild(controls);
    linesEl.appendChild(line);
  }
  linesEl.querySelectorAll("[data-dec]").forEach((b) => (b.onclick = () => setQty(b.dataset.dec, -1)));
  linesEl.querySelectorAll("[data-inc]").forEach((b) => (b.onclick = () => setQty(b.dataset.inc, 1)));
  linesEl.querySelectorAll("[data-remove]").forEach((b) => (b.onclick = () => setQty(b.dataset.remove, -9999)));

  emptyEl.hidden = cart.length > 0;

  const sub = subtotal();
  const discount = Math.round(sub * (discountPct / 100));
  const taxed = sub - discount;
  const vat = Math.round(taxed * VAT_RATE);
  const grand = taxed + vat;

  totalsEl.innerHTML = `
    <div class="row"><span>Subtotal</span><span data-total="subtotal">${naira(sub)}</span></div>
    ${discountPct ? `<div class="row"><span>Discount (${discountPct}%)</span><span data-total="discount">−${naira(discount)}</span></div>` : ""}
    <div class="row"><span>VAT (7.5%)</span><span data-total="vat">${naira(vat)}</span></div>
    <div class="row grand"><span>Total</span><span data-total="grand">${naira(grand)}</span></div>`;
}

async function applyCoupon() {
  const code = document.getElementById("coupon").value.trim();
  couponMsg.textContent = "";
  couponMsg.className = "";
  if (!code) return;
  try {
    const res = await fetch(`/api/coupon?code=${encodeURIComponent(code)}`);
    if (!res.ok) throw new Error("bad status");
    const data = await res.json();
    if (data.valid) {
      discountPct = data.percentOff;
      couponMsg.textContent = `Applied — ${data.percentOff}% off.`;
      couponMsg.className = "ok";
    } else {
      discountPct = 0;
      couponMsg.textContent = "That code isn't valid.";
      couponMsg.className = "bad";
    }
  } catch {
    couponMsg.textContent = "Couldn't check that code — try again.";
    couponMsg.className = "bad";
  }
  render();
}

document.getElementById("apply").addEventListener("click", applyCoupon);

renderCatalog();
render();

const { defineConfig } = require("cypress");

module.exports = defineConfig({
  e2e: {
    baseUrl: "http://localhost:5173",
    supportFile: false,
    fixturesFolder: false,
    video: false,
  },
});

describe("cart-checks", () => {
  beforeEach(() => {
    cy.visit("/");
  });

  it("adds items and computes subtotal, VAT and total", () => {
    cy.contains(".product", "Honey beans").find("[data-add]").click();
    cy.contains(".product", "Groundnut oil").find("[data-add]").click();

    cy.get('[data-total="subtotal"]').should("have.text", "₦4,400.00");
    cy.get('[data-total="vat"]').should("have.text", "₦330.00");
    cy.get('[data-total="grand"]').should("have.text", "₦4,730.00");
  });

  it("updates totals when quantity changes", () => {
    cy.contains(".product", "Honey beans").find("[data-add]").click();
    cy.get('[data-inc="beans"]').click().click();

    cy.get('[data-qty="beans"]').should("have.text", "3");
    cy.get('[data-total="subtotal"]').should("have.text", "₦5,400.00");
  });

  it("shows the empty-cart message after removing the last item", () => {
    cy.contains(".product", "Honey beans").find("[data-add]").click();
    cy.get("#empty").should("not.be.visible");

    cy.get('[data-remove="beans"]').click();
    cy.get("#empty").should("be.visible").and("contain", "empty");
  });

  it("applies a valid coupon from the API", () => {
    cy.intercept("GET", "/api/coupon*", {
      statusCode: 200,
      body: { valid: true, percentOff: 10 },
    }).as("coupon");

    cy.contains(".product", "Basmati rice").find("[data-add]").click();
    cy.get("#coupon").type("SAVE10");
    cy.get("#apply").click();

    cy.wait("@coupon");
    cy.get("#coupon-msg").should("have.class", "ok").and("contain", "10% off");
    cy.get('[data-total="discount"]').should("have.text", "−₦950.00");
    cy.get('[data-total="grand"]').should("have.text", "₦9,191.00");
  });

  it("keeps the total unchanged when the coupon service fails", () => {
    cy.intercept("GET", "/api/coupon*", { statusCode: 500, body: {} }).as("coupon");

    cy.contains(".product", "Basmati rice").find("[data-add]").click();
    cy.get('[data-total="grand"]').then(($el) => {
      const before = $el.text();
      cy.get("#coupon").type("SAVE10");
      cy.get("#apply").click();
      cy.wait("@coupon");
      cy.get("#coupon-msg").should("have.class", "bad").and("contain", "Couldn't check");
      cy.get('[data-total="grand"]').should("have.text", before);
    });
  });

  // Deliberately failing — this is the good-first-issue. Add a
  // "Proceed to checkout" button that is disabled while the cart is empty.
  it("disables checkout when the cart is empty", () => {
    cy.contains("button", "Proceed to checkout").should("be.disabled");
  });
});

{
  "name": "cart-checks",
  "version": "1.0.0",
  "private": true,
  "description": "Shopping cart with coupons + VAT, tested with Cypress.",
  "scripts": {
    "start": "node serve.js",
    "cy:run": "cypress run",
    "cy:open": "cypress open",
    "test": "start-server-and-test start http://localhost:5173 cy:run"
  },
  "devDependencies": {
    "cypress": "^13.15.0",
    "start-server-and-test": "^2.0.8"
  }
}

// Zero-dependency static server + a tiny coupon endpoint, so the page works
// both when you open it manually and when Cypress drives it.
const http = require("http");
const fs = require("fs");
const path = require("path");

const PORT = process.env.PORT || 5173;
const ROOT = __dirname;
const TYPES = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" };

const COUPONS = { SAVE10: 10, WELCOME5: 5 };

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);

  if (url.pathname === "/api/coupon") {
    const code = (url.searchParams.get("code") || "").toUpperCase();
    const percentOff = COUPONS[code];
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify(percentOff ? { valid: true, percentOff } : { valid: false }));
    return;
  }

  let file = url.pathname === "/" ? "/index.html" : url.pathname;
  const full = path.join(ROOT, path.normalize(file));
  if (!full.startsWith(ROOT) || !fs.existsSync(full)) {
    res.writeHead(404).end("Not found");
    return;
  }
  res.writeHead(200, { "content-type": TYPES[path.extname(full)] || "text/plain" });
  fs.createReadStream(full).pipe(res);
});

server.listen(PORT, () => console.log(`cart-checks on http://localhost:${PORT}`));
